parameters.jsonBody:
{
  "message": "Give a 5-line water-risk summary for Bangladesh today, using BlueSense data.",
  "region": "bd",
  "clientId": "n8n-daily-digest"
}

parameters.jsCode:
// Builds the digest from the Copilot stream (this node's input) and the dashboard summary.
// Copilot stream: server-sent events "event: <type>" + "data: <json>"; types tool, delta (answer text), done, error.
const raw = String($input.first().json.data ?? '');
const summary = $('Get dashboard summary').first().json;
const base = 'https://bluesense-api-preview-ca2-2uju3.vercel.app';

// 1. Copilot answer: join the text of every delta event.
const events = [];
for (const block of raw.replace(/\r\n/g, '\n').split('\n\n')) {
  let type = null;
  const data = [];
  for (const line of block.split('\n')) {
    if (line.startsWith('event:')) type = line.slice(6).trim();
    else if (line.startsWith('data:')) data.push(line.slice(5).replace(/^ /, ''));
  }
  if (!data.length) continue;
  try {
    const ev = JSON.parse(data.join('\n'));
    events.push({ ...ev, type: ev.type ?? type });
  } catch (e) { /* ignore a malformed event */ }
}
const answer = events.filter(e => e.type === 'delta').map(e => e.text ?? '').join('').trim();
const done = events.find(e => e.type === 'done');
let problem = events.find(e => e.type === 'error');
if (!events.length) {
  // Not a stream: an HTTP error body such as {"code": "site_daily_limit", "detail": "..."}
  try {
    const j = JSON.parse(raw);
    problem = { code: j.code ?? j.error?.code ?? 'http_error', detail: j.detail ?? j.error?.detail ?? j.message ?? raw.slice(0, 200) };
  } catch (e) {
    problem = { code: 'no_response', detail: raw ? raw.slice(0, 200) : 'Empty response from the Copilot.' };
  }
}
const copilotOk = Boolean(answer) && !problem;

// 2. Key KPIs from /api/dashboard/summary.
const d = summary.data ?? {};
const meta = summary.meta ?? {};
const kpi = key => (d.kpis ?? []).find(k => k.key === key);
const num = (x, signed = false) => {
  const r = Math.round(Number(x) * 10) / 10;
  return (signed && r > 0 ? '+' : '') + r;
};
const kpiLine = (key, name) => {
  const k = kpi(key);
  if (!k || k.value?.value == null) return `- ${name}: not available`;
  let s = `- ${name}: ${num(k.value.value, key === 'groundwater')} ${k.value.unit ?? ''}`.trimEnd();
  if (k.value.observedAt) s += ` (${k.value.observedAt})`;
  if (k.classLabel) s += `, ${k.classLabel}`;
  if (k.comparison?.value != null && k.comparisonLabel && Number(k.comparison.value) !== 0) {
    s += `, ${num(k.comparison.value, true)} ${k.comparison.unit ?? ''} ${k.comparisonLabel}`.replace(/ +/g, ' ');
  }
  return s;
};
const kpiLines = [
  kpiLine('utilization', 'Water stress (SDG 6.4.2)'),
  kpiLine('groundwater', 'Water storage anomaly (GRACE)'),
  `- Open alerts: ${d.openAlerts ?? 'n/a'}`,
  `- Data status: ${meta.status ?? 'unknown'}${meta.retrieved_at ? `, last refreshed ${String(meta.retrieved_at).slice(0, 16).replace('T', ' ')} UTC` : ''}`,
];

// 3. Subject and body.
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Dhaka' });
const subject = `BlueSense water-risk digest: Bangladesh, ${today}${copilotOk ? '' : ' (Copilot unavailable)'}`;
const body = [
  `BlueSense daily water-risk digest for Bangladesh, ${today}`,
  '',
  'Copilot summary:',
  copilotOk ? answer : `The Copilot gave no answer today (${problem?.code ?? 'empty'}: ${problem?.detail ?? 'no text'}).`,
  '',
  'Key indicators:',
  ...kpiLines,
  '',
  `Source: BlueSense API (${base})${done ? `; answer written by ${done.provider} ${done.model}` : ''}.`,
  'BlueSense is a decision-support prototype; AI answers can contain errors. Check the dashboard before acting.',
].join('\n');

return [{ json: { subject, body, copilotOk, copilotError: problem ?? null, model: done?.model ?? null } }];
